method strlen(string: string) returns (length: int)
    requires string != null
    ensures length >= 0
    ensures length == |string|
{
    length := 0;
    var i := 0;
    while i < |string|
        invariant 0 <= i <= |string|
        invariant length == i
    {
        i := i + 1;
    }
    length := i;
}
